
import base64
import sys

def _d(data, key):
    """Decryption routine"""
    decoded = base64.b64decode(data).decode('latin-1')
    result = []
    for i, char in enumerate(decoded):
        key_char = key[i % len(key)]
        result.append(chr(ord(char) ^ ord(key_char)))
    return ''.join(result)

